import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.Dh6DF7gt.js";const f=JSON.parse('{"title":"使用指南","description":"了解智能办公室文档库的导航、搜索、阅读与维护方法。","frontmatter":{"title":"使用指南","description":"了解智能办公室文档库的导航、搜索、阅读与维护方法。"},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1785501020000}'),d={name:"guide/getting-started.md"};function l(o,a,s,c,h,n){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><p>这个文档库用来连接方案、任务和现场证据。只是查看项目时，按“总览→专题→验收”阅读；需要推进工作时，按“查现状→建 Issue→更新文档”操作。</p><h2 id="先选择你的路径" tabindex="-1">先选择你的路径 <a class="header-anchor" href="#先选择你的路径" aria-label="Permalink to &quot;先选择你的路径&quot;">​</a></h2><h3 id="我只想查看项目" tabindex="-1">我只想查看项目 <a class="header-anchor" href="#我只想查看项目" aria-label="Permalink to &quot;我只想查看项目&quot;">​</a></h3><ol><li>先看<a href="/ai-lab-smart-office/guide/project-overview">项目总览</a>，了解目标、范围和建议阶段。</li><li>再看<a href="/ai-lab-smart-office/guide/office-layout">办公室布局</a>，确认房间名称、功能分区和图纸边界。</li><li>根据关心的专题进入<a href="/ai-lab-smart-office/guide/architecture">当前网络现状</a>、<a href="/ai-lab-smart-office/implementation/smart-office-plan">智能化总体方案</a>或<a href="/ai-lab-smart-office/implementation/automation">自动化场景</a>。</li><li>需要核对采购和交付时，查看<a href="/ai-lab-smart-office/management/procurement">采购与设备台账</a>和<a href="/ai-lab-smart-office/management/acceptance">施工与验收</a>。</li></ol><h3 id="我需要维护或推进项目" tabindex="-1">我需要维护或推进项目 <a class="header-anchor" href="#我需要维护或推进项目" aria-label="Permalink to &quot;我需要维护或推进项目&quot;">​</a></h3><ol><li>先阅读<a href="/ai-lab-smart-office/guide/workflow">协作与变更流程</a>，确认这项工作应进入文档、Issue 还是决策记录。</li><li>搜索已有页面和 Issue，避免建立两份相互冲突的记录。</li><li>新增费用、变更设备型号或布线、修改自动化规则、发现现场问题时，先建 Issue。</li><li>结论稳定后修改对应的 Markdown 文档；有重要取舍时，同步更新<a href="/ai-lab-smart-office/guide/decision-log">决策记录</a>。</li></ol><h2 id="怎么导航和搜索" tabindex="-1">怎么导航和搜索 <a class="header-anchor" href="#怎么导航和搜索" aria-label="Permalink to &quot;怎么导航和搜索&quot;">​</a></h2><h3 id="顶部导航" tabindex="-1">顶部导航 <a class="header-anchor" href="#顶部导航" aria-label="Permalink to &quot;顶部导航&quot;">​</a></h3><p>顶部导航用来切换项目大类。进入一个大类后，再用左侧目录选择具体页面，不必反复回到首页。</p><h3 id="左侧目录" tabindex="-1">左侧目录 <a class="header-anchor" href="#左侧目录" aria-label="Permalink to &quot;左侧目录&quot;">​</a></h3><p>左侧目录展示当前项目路径，高亮项表示正在阅读的页面。如果你不确定下一页看什么，按目录从上到下阅读即可。</p><h3 id="本页目录" tabindex="-1">本页目录 <a class="header-anchor" href="#本页目录" aria-label="Permalink to &quot;本页目录&quot;">​</a></h3><p>较长页面会显示“本页目录”，桌面端通常位于右侧。点击二级或三级标题，可直接跳到当前页的对应部分。</p><h3 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to &quot;搜索&quot;">​</a></h3><ul><li>点击页面顶部的“搜索方案、设备、房间…”，或按 <code>⌘ K</code>（macOS）/ <code>Ctrl K</code>（Windows、Linux）。</li><li>输入房间名称、设备类型、协议、场景或任务，例如“D会议室”、“窗帘”、“VLAN”或“验收”。</li><li>用方向键切换结果，按 Enter 打开，按 Esc 关闭。</li><li>搜索结果会直接定位到页面标题；打开后先确认所在页面和章节，再开始执行。</li></ul><h2 id="信息应该放在哪里" tabindex="-1">信息应该放在哪里 <a class="header-anchor" href="#信息应该放在哪里" aria-label="Permalink to &quot;信息应该放在哪里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>信息类型</th><th>存放位置</th><th>例子</th></tr></thead><tbody><tr><td>范围、空间、现状、协作规则和技术决策</td><td><code>docs/guide/</code></td><td>项目总览、办公室布局、当前网络现状、决策记录</td></tr><tr><td>技术方案、实施要求和自动化规则</td><td><code>docs/implementation/</code></td><td>网络与弱电规划、智能化总体方案、自动化场景</td></tr><tr><td>采购、设备台账、施工与验收</td><td><code>docs/management/</code></td><td>报价选择、资产信息、验收结论</td></tr><tr><td>网页需要展示或下载的图纸与图表</td><td><code>docs/public/</code></td><td>SVG、PNG、PDF 和 CAD 下载包</td></tr><tr><td>待决、待做、现场问题或待验收事项</td><td>GitHub Issue</td><td>采购设备、修复 AP 覆盖盲区、场景测试不通过</td></tr><tr><td>对文档、图纸或配置的可审核变更</td><td>Pull Request</td><td>更新 VLAN 方案、修正点位或补充验收证据</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">不要写入仓库</p><p>密码、私钥、令牌、门禁凭证和个人敏感信息不得提交到文档、Issue 或 Pull Request。</p></div><h2 id="推进一项工作-1—2—3" tabindex="-1">推进一项工作：1—2—3 <a class="header-anchor" href="#推进一项工作-1—2—3" aria-label="Permalink to &quot;推进一项工作：1—2—3&quot;">​</a></h2><h3 id="_1-查-确认现状和边界" tabindex="-1">1. 查：确认现状和边界 <a class="header-anchor" href="#_1-查-确认现状和边界" aria-label="Permalink to &quot;1. 查：确认现状和边界&quot;">​</a></h3><p>先搜索相关房间、设备或系统，阅读现有方案、警告和待确认项。如果文档与现场不一致，先记录差异，不直接把假设当成结论。</p><h3 id="_2-做-用-issue-明确责任和验收方式" tabindex="-1">2. 做：用 Issue 明确责任和验收方式 <a class="header-anchor" href="#_2-做-用-issue-明确责任和验收方式" aria-label="Permalink to &quot;2. 做：用 Issue 明确责任和验收方式&quot;">​</a></h3><p>记录范围、区域或设备编号、负责人、预算或影响、成功标准和相关证据。涉及重要取舍时，建立或关联决策记录。</p><h3 id="_3-记-让文档与现场重新一致" tabindex="-1">3. 记：让文档与现场重新一致 <a class="header-anchor" href="#_3-记-让文档与现场重新一致" aria-label="Permalink to &quot;3. 记：让文档与现场重新一致&quot;">​</a></h3><p>完成实施或评审后，更新对应方案、图纸、设备台账和验收记录，关联 Issue 与测试证据。页面底部的“在 GitHub 中编辑此页”可作为文档修改入口。</p><div class="tip custom-block"><p class="custom-block-title">最简单的判断</p><p>查结论，看文档；推任务，建 Issue；改结论，提 Pull Request；做了重要取舍，补决策记录。</p></div>',27)])])}const m=e(d,[["render",l]]);export{f as __pageData,m as default};
